        for f in ('as','prod','card','pr'):
            if k.get(f): A.select_option('#fc-'+f,k[f])
        if k.get('lb'): A.fill('#fc-lb',k['lb'])
        if k.get('due'): A.fill('#fc-due',k['due'])
