    A.click('button:text-is("Close")'); A.wait_for_timeout(200)
    A.goto(URL+'#/flow/issue/YNMO-3'); A.wait_for_timeout(2200)
    ok('R13 opening a ticket link shows that ticket in its window', A.locator('#fi-title').count()==1 and A.locator('#fi-title').input_value()=='Crash on pay')
