    ok('R35 deleting an epic keeps its tickets, which lose the epic', A.locator('.flowrow',has_text='Payments').count()==0 and A.locator('.flowrow',has_text='Epic child').count()==1 and A.evaluate("Object.values(JSON.parse(localStorage.getItem('fk3')).flow_issues).find(i=>i.t==='Epic child').ep")=='')
